import {nextTownCard,townHistory,errandValid,startTown,chooseTown,checkTown,keepTown,asideTown,supportTown} from './town-remembers-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attr,label,disabled=false)=>`<button type="button" ${attr} class="${attr.includes('data-town-start')||attr.includes('data-town-check')?'primary':'secondary'}" ${disabled?'disabled':''}>${esc(label)}</button>`;
const marks=[0,100,200,300,400,500];
function jugArt(amount,{secret=false,target=null}={}){
 const lower=(Math.ceil(amount/100)-1)*100,upper=(Math.floor(amount/100)+1)*100;
 const level=amount%100===0?`at the numbered ${amount} mL mark`:`halfway between the ${lower} and ${upper} mL numbered marks`;
 return `<figure class="town-jug"><div class="town-jug-drawing" role="img" aria-label="${esc(`A straight-sided model jug. Numbered marks from zero to five hundred in hundreds, with unnumbered halfway marks. The liquid reaches ${level}${target===null?'':`; dashed target at ${target} mL`}.`)}"><div class="town-jug-liquid" style="height:${amount/5}%"></div>${Array.from({length:11},(_,i)=>`<span class="town-jug-tick ${i%2===0?'major':'mid'}" style="bottom:${i*10}%">${i%2===0?`${i*50} mL`:''}</span>`).join('')}${target===null?'':`<span class="town-jug-target" style="bottom:${target/5}%">target</span>`}</div><figcaption>${secret?'The same amount, shown on another scale.':`Start: ${amount} mL${target===null?'':` · Target: ${target} mL`}`}</figcaption></figure>`;
}
function bar(n,width,selected=[],compare=false){return `<div class="town-share-bar" role="img" aria-label="${esc(`${compare?'Comparison of the same':'Kept'} loaf, width ${width}, divided into ${n} equal pieces${selected.length?`; saved selected piece ${selected.map(x=>x+1).join(', ')}`:''}${compare?'; one piece is marked only for this comparison':''}.`)}">${Array.from({length:n},(_,i)=>`<span class="${selected.includes(i)?'town-selected':''}" aria-hidden="true">${compare&&i===0?'<i title="Comparison piece">◆</i>':''}</span>`).join('')}</div>`;}
function buns(groups=null){return groups===null?`<div class="town-buns" role="img" aria-label="Twelve unselected buns in a basket">${Array.from({length:12},()=>'<span aria-hidden="true">●</span>').join('')}</div>`:`<div class="town-bun-groups" role="img" aria-label="Twelve buns in ${groups} equal groups of ${12/groups}; one group outlined">${Array.from({length:groups},(_,i)=>`<div class="${i===0?'town-group-outline':''}">${Array.from({length:12/groups},()=>'<span aria-hidden="true">●</span>').join('')}</div>`).join('')}</div>`;}
function helpPicture(e){const x=e.example;
 if(x.kind==='trays')return `<div class="town-picture-grid town-example-art"><div class="town-small-jar">cloud-water <strong>${x.cloud} mL</strong></div><div class="town-small-jar">star-water <strong>${x.star} mL</strong></div><div class="town-guests" role="img" aria-label="${x.guests} guests in equal pairs">${Array.from({length:x.guests/2},()=>'<span>● ●</span>').join('')}</div></div>`;
 if(x.kind==='shortcut')return `<div class="town-example-art"><div class="town-picture-grid"><div class="town-small-jar">cloud-water ${x.cloud} mL</div><div class="town-small-jar">star-water ${x.star} mL</div></div><p>Wisp adds 100 mL to each jar ↓</p><div class="town-picture-grid town-proposal"><div>${x.proposedCloud} mL cloud-water</div><div>${x.proposedStar} mL star-water</div></div></div>`;
 if(x.kind==='shares')return `<div class="town-example-art"><p>Same whole, ${x.n} shares</p>${bar(x.n,x.width,[],true)}<p>Same whole, ${x.m} shares</p>${bar(x.m,x.width,[],true)}</div>`;
 if(x.kind==='buns')return `<div class="town-example-art">${buns(x.n)}</div>`;
 if(x.kind==='jug')return `<div class="town-example-art">${jugArt(x.amount)}</div>`;
 return `<div class="town-example-art">${jugArt(x.start,{target:x.target})}<p>Separate example pour: ${x.extra} mL → ${x.target} mL.</p></div>`;
}
function picture(e){const v=e.artifact.values,f=e.form;
 if(f==='trays-reverse'||f==='trays-shortcut')return `<div class="town-picture-grid"><div class="town-small-jar"><span aria-hidden="true">•••</span> cloud-water <strong>${v.cloud} mL</strong></div><div class="town-small-jar"><span aria-hidden="true">///</span> star-water <strong>${v.star} mL</strong></div></div>${f==='trays-shortcut'?`<div class="town-picture-grid town-proposal" aria-label="Wisp's proposed jars"><div>Proposed cloud-water <strong>${v.cloud+100} mL</strong></div><div>Proposed star-water <strong>${v.star+100} mL</strong></div></div><p>Jar capacity: 500 mL each. One batch: 100 mL cloud-water and 150 mL star-water.</p>`:'<p>Reference card: 2 guests need 100 mL cloud-water and 150 mL star-water.</p>'}`;
 if(f==='share-compare'){const m=v.m;return `<p>Kept loaf: ${v.n} equal pieces. The diamond marks a comparison piece; green marks any saved selection.</p>${bar(v.n,v.width,v.selected,true)}<p>Clover cuts the same ${esc(v.wholeId)} loaf: ${m} equal pieces</p>${bar(m,v.width,[],true)}`;}
 if(f==='share-buns')return `<p>One saved piece of ${v.n} equal parts: 1/${v.n} of this loaf.</p>${bar(v.n,v.width,v.selected)}<p>Twelve unselected buns:</p>${buns()}`;
 if(f==='jug-coarser')return `<div class="town-picture-grid"><div class="town-opaque-jar" role="img" aria-label="Remembered ${esc(v.ingredient)} jar, no amount shown">Remembered ${esc(v.ingredient)} jar</div>${jugArt(v.a,{secret:e.checks.length===0})}</div>${e.checks.length?`<p>Saved amount: ${v.a} mL.</p>`:''}`;
 return jugArt(v.a,{target:v.t});
}
function readableErrand(e){const open=e.status==='open',last=e.checks.at(-1);
 return `<section class="town-card" aria-labelledby="town-question"><h2 id="town-question" tabindex="-1">A neighbour remembers</h2><p class="town-source"><strong>${esc(e.artifact.title)}</strong> · An idea you kept on an earlier day${e.familiar?' · A familiar question form':''}.</p><section class="town-remembered" aria-label="Remembered artefact"><h3>The idea you kept</h3>${picture(e)}<p class="tiny">${esc(e.picture)}</p></section><section class="town-new-question"><h3>A new errand</h3><p>${esc(e.question)}</p><fieldset ${open?'':'disabled'}><legend>Choose an idea</legend>${e.choices.map((c,i)=>`<label class="town-choice"><input type="radio" name="town-choice" value="${i}" ${e.choice===c.value?'checked':''}><span>${esc(c.label)}</span></label>`).join('')}</fieldset>${open?`<div class="town-actions">${button('data-town-check','Check this idea',e.choice===null||e.checks.length>=8)}${button('data-town-keep','Keep this answer',e.choice===null)}${button('data-town-aside','Set aside')}</div>${e.checks.length>=8?'<p>Eight checks are kept here. You can still choose and keep an answer or set this aside.</p>':''}`:`<p class="town-finished">${e.status==='aside'?'Another time, then.':`Answer kept: ${esc(e.choices.find(c=>c.value===e.choice)?.label||'')}`}</p>`}${last?`<div class="town-feedback" role="status"><p>${esc(last.feedback)}</p>${open?'<p>Choose another idea if you like. Nothing here changes your earlier work.</p>':''}</div>`:''}</section>${open?`<aside class="town-support"><h3>Thinking together</h3>${button('data-town-support="example"','Try a different example')}${e.support.example?`<p class="town-example">${esc(e.help)}</p>${helpPicture(e)}`:''}${button('data-town-support="together"',e.support.together?'Working together recorded':'We worked it out together')}<span data-town-audio>${hearButton(`${e.question} ${e.support.example?e.help:''}`,'Hear this errand')}</span><p class="tiny">Help, working together and voice requests are noted separately. Your original artefact stays as it was.</p></aside>`:''}</section>`;
}
export function townInvitation(state){const card=nextTownCard(state);if(!card)return '';const label=card.type==='offer'?`${{trays:'Purl remembers your tray',shares:'Clover remembers your loaf',jugs:'Wisp remembers your kitchen jar'}[card.artifact.kind]} from ${card.artifact.title}.`:card.type==='open'?'A neighbour is waiting with your earlier idea.':'An earlier errand needs a fresh page.';return `<section class="town-invitation" aria-label="A neighbour remembers"><div><h2>A neighbour remembers</h2><p>${esc(label)}</p></div><a class="secondary" href="#town/remembers">${card.type==='offer'?'Visit this neighbour':'Continue the errand'}</a></section>`;}
export function townPage(state,detail=null){const card=nextTownCard(state),heading='<header class="page-heading"><a class="back" href="#home">← Back to the garden</a><h1>The Town Remembers</h1><p>An earlier idea returns in another form. Take your time, ask for help, or leave it for another day.</p></header>';
 if(detail&&/^\d+$/.test(detail)){const e=townHistory(state).readable.find(x=>x.id===Number(detail));if(e)return `<div class="town-page">${heading}${readableErrand(e)}<p><a class="secondary" href="#town/remembers">See the next neighbour</a></p></div>`;}
 if(!card)return `<div class="town-page">${heading}<section class="town-card"><h2>No neighbour is waiting just now</h2><p>Keep a tray, loaf, or kitchen jar. A neighbour may return with an errand on a later day.</p><a href="#cafe">Explore the café</a></section></div>`;
 if(card.type==='unavailable')return `<div class="town-page">${heading}<section class="town-card"><h2>An earlier errand is safe</h2><p>This saved errand cannot be read in this version. Its original record remains in the notes and download.</p>${button('data-town-aside','Set aside this errand')}<p><a href="#notes">Grown-up notes</a></p></section></div>`;
 if(card.type==='open')return `<div class="town-page">${heading}${readableErrand(card.errand)}<p><a href="#notes">Grown-up notes</a></p></div>`;
 return `<div class="town-page">${heading}<section class="town-card"><h2>${esc({trays:'Purl remembers your tray',shares:'Clover remembers your loaf',jugs:'Wisp remembers your kitchen jar'}[card.artifact.kind])}</h2><p>${esc(card.artifact.title)} · Kept on an earlier day. A new question waits beside your earlier work.</p>${card.willTrim===null?'':`<p class="town-history-notice">Starting this errand will remove the oldest finished errand (visit ${card.willTrim}) from this notebook. Download notes first if you want that visit.</p>`}${button('data-town-start','Start this errand')}<p><a href="#cafe">Explore somewhere else</a></p></section></div>`;
}
export function bindTown(state,{save,render,navigate,focus}){
 const act=(selector,fn,target='#town-question, .town-card h2')=>document.querySelector(selector)?.addEventListener('click',()=>{if(fn()){save();render();focus(target);}});
 act('[data-town-start]',()=>startTown(state));act('[data-town-check]',()=>checkTown(state),'.town-feedback');
 const finish=(selector,fn)=>document.querySelector(selector)?.addEventListener('click',()=>{const id=nextTownCard(state)?.errand?.id;if(!fn(state))return;save();navigate(Number.isSafeInteger(id)&&id>0?`#town/remembers/${id}`:'#town/remembers');});
 finish('[data-town-keep]',keepTown);finish('[data-town-aside]',asideTown);
 document.querySelectorAll('input[name="town-choice"]').forEach(input=>input.addEventListener('change',()=>{const card=nextTownCard(state);if(card?.type!=='open')return;const choice=card.errand.choices[Number(input.value)];if(choice&&chooseTown(state,choice.value)){save();render();focus(`input[name="town-choice"][value="${input.value}"]`);}}));
 document.querySelectorAll('[data-town-support]').forEach(b=>b.addEventListener('click',()=>{if(supportTown(state,b.dataset.townSupport)){save();render();focus(`[data-town-support="${b.dataset.townSupport}"]`);}}));
 document.querySelector('[data-town-audio] [data-speak]')?.addEventListener('click',()=>{if(supportTown(state,'narration'))save();});
}
export function townNotes(state){if(!Object.hasOwn(state,'townRemembers'))return '';const h=townHistory(state);return `<details class="panel town-notes"><summary>The Town Remembers (${h.readable.length} readable errands)</summary><p>These are explorations after a gap, not evidence of mastery. Dates follow this device’s local calendar. Support and familiarity are separate from the answer.</p>${h.readable.map(e=>`<section><h3>Visit ${e.id}: ${esc(e.artifact.title)}</h3><p>${esc(e.kind)} · ${esc(e.form)} · ${e.artifact.keptDay?`kept on ${esc(e.artifact.keptDay)}; returned on ${esc(e.startedDay)}`:`kept on an earlier day, date unknown; returned on ${esc(e.startedDay)}`}. ${esc(e.status)}.</p><p>Choices: ${e.choices.map(c=>esc(c.label)).join(' / ')}. ${e.choice===null?'No final choice yet.':`Current or final choice: ${esc(e.choices.find(c=>c.value===e.choice)?.label)}.`}</p><p>Support: ${Object.entries(e.support).filter(([,v])=>v).map(([k])=>k).join(', ')||'none recorded'}. Familiar form: ${e.familiar?'yes':'no'}.</p>${e.checks.map((c,i)=>`<p>Check ${i+1}: ${esc(e.choices.find(x=>x.value===c.choice)?.label)}. ${c.fit?'Fits':'Another idea'}. ${esc(c.feedback)}</p>`).join('')}<a href="#town/remembers/${e.id}">Read this errand</a></section>`).join('')}${h.raw.length?`<details><summary>Earlier unreadable work (${h.raw.length})</summary><pre>${esc(JSON.stringify(h.raw,null,2))}</pre></details>`:''}</details>`;}
